function button(text,action,cls=""){return '<button type="button" class="btn '+cls+'" data-action="'+esc(action)+'">'+text+"</button>"}
function shell(label,title,desc,body=""){return '<div class="page"><div class="head"><div><small>'+label+"</small><h1>"+title+'</h1><p>'+desc+"</p></div></div>"+body+"</div>"}
function nav(){let a=[...base];if(me)a.push(["logout","↪","تسجيل خروج"]);if(me&&["admin","owner"].includes(me.role))a.push(["admin","⚙","الإدارة"]);if(me?.role==="owner")a.push(["owner","♛","لوحة الأونر"]);const current=(location.hash.slice(1)||"home");const make=(x)=>'<button type="button" data-page="'+x[0]+'" class="'+(x[0]===current?"active":"")+'" '+(x[0]===current?'aria-current="page"':"")+'><i aria-hidden="true">'+x[1]+"</i>"+x[2]+"</button>";$("#nav").innerHTML=a.map(make).join("");$("#topnav").innerHTML=a.slice(0,5).map(make).join("");$("#mobile").innerHTML=a.map(make).join("");const menu=$("#menu");if(menu)menu.setAttribute("aria-expanded",String($("#mobile").classList.contains("open")))}
function go(p){if((location.hash.slice(1)||"home")===p){page();return}location.hash=p}
