async function roles(){getApp().innerHTML=shell("LEADERSHIP","الرتب القيادية","Owner وCo-Owner وFounder وStaff الثلاث.",'<div id="roles" class="grid"></div>');try{const d=await api("/api/public/roles");$("#roles").innerHTML=(d.roles||[]).map(r=>'<article class="role" data-role="'+r.id+'"><em style="background:'+esc(r.color)+'"></em><small>'+num(r.membersCount)+" عضو</small><h2>"+esc(r.name)+"</h2></article>").join("");$$("[data-role]").forEach(x=>x.onclick=async()=>{const d=await api("/api/public/roles/"+x.dataset.role+"/members");modal("<h2>"+esc(d.role.name)+"</h2><div class=\"grid mini\">"+d.members.map(m=>'<article class=\"member\"><img src="'+esc(m.avatar)+'"><b>'+esc(m.name)+"</b></article>").join("")+"</div>")})}catch(e){toast(e.message)}}
function auth(){getApp().innerHTML=shell("ACCOUNT","تسجيل الدخول","لا يوجد Discord OAuth. الحساب باسم وكلمة مرور مع تحقق Discord.",'<div class="tabs"><button id="lt" class="active">دخول</button><button id="rt">تسجيل</button></div><div id="auth"></div>');const login=()=>{$("#auth").innerHTML='<form id="lf" class="form"><input class="input" name="username" placeholder="اسم المستخدم" required><input class="input" name="password" type="password" placeholder="كلمة المرور" required><button class="btn primary">دخول</button></form>';$("#lf").onsubmit=async e=>{e.preventDefault();try{const d=await api("/api/auth/login",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});token=d.token;localStorage.setItem("mld_token",token);me=d.user;nav();go("home");toast("تم الدخول")}catch(x){toast(x.message)}}};const reg=()=>{$("#auth").innerHTML='<form id="rf" class="form"><input class="input" name="username" placeholder="اسم المستخدم" required><input class="input" name="password" type="password" minlength="8" placeholder="كلمة المرور" required><label class="suggest-wrap"><span>اسم مستخدم Discord</span><input class="input" id="discordUsername" name="discordUsername" autocomplete="off" placeholder="اكتب اسم العضو" required><div id="discord-suggestions" class="suggestions hidden"></div></label><button class="btn primary">إرسال رمز Discord</button></form>';wireDiscordAutocomplete($("#discordUsername"),$("#discord-suggestions"));
$("#rf").onsubmit=async e=>{e.preventDefault();try{await api("/api/auth/register",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});modal('<form id="vf" class="form"><h2>تفعيل الحساب</h2><input class="input" name="code" placeholder="الرمز الذي وصلك بالخاص"><button class="btn primary">تفعيل</button></form>');$("#vf").onsubmit=async v=>{v.preventDefault();try{const d=await api("/api/auth/verify",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(v.target)))});token=d.token;localStorage.setItem("mld_token",token);me=d.user;closeModal();nav();go("home")}catch(x){toast(x.message)}}}catch(x){toast(x.message)}}};$("#lt").onclick=login;$("#rt").onclick=reg;login()}
function wireDiscordAutocomplete(input,box){if(!input||!box)return;let timer;input.addEventListener("input",()=>{clearTimeout(timer);const q=input.value.trim();if(q.length<2){box.classList.add("hidden");box.innerHTML="";return}timer=setTimeout(async()=>{try{const d=await api("/api/discord/members?q="+encodeURIComponent(q));box.innerHTML=(d.members||[]).map(m=>'<button type="button" class="suggestion" data-suggest="'+esc(m.username)+'"><img src="'+esc(m.avatar||"/logo.svg.JPG")+'"><span><b>'+esc(m.name)+'</b><small>@'+esc(m.username)+'</small></span></button>').join("")||'<div class="suggest-empty">لا توجد اقتراحات مطابقة</div>';box.classList.remove("hidden");box.querySelectorAll("[data-suggest]").forEach(b=>b.onclick=()=>{input.value=b.dataset.suggest;box.classList.add("hidden");box.innerHTML=""})}catch(e){box.classList.add("hidden")}},160)});document.addEventListener("click",e=>{if(!box.contains(e.target)&&e.target!==input)box.classList.add("hidden")})}
async function ai(){getApp().innerHTML=shell("MLD INTELLIGENCE","مساعد ملاذ الذكي","مساعد محادثة ذكي داخل المنصة. تتطلب الخدمة مفتاح مزوّد AI في إعدادات Railway.",'<section class="ai-shell"><div class="ai-intro"><div class="ai-orb">✧</div><div><h2>كيف أقدر أساعدك؟</h2><p>اسأل عن الموقع أو البرمجة أو Discord أو اطلب أفكاراً لمجتمعك.</p></div></div><div id="ai-messages" class="ai-messages"><div class="ai-message assistant"><b>MLD AI</b><p>أهلًا بك! أنا مساعد ملاذ. اكتب سؤالك وسأحاول مساعدتك خطوة بخطوة.</p></div></div><form id="ai-form" class="ai-compose"><textarea id="ai-input" class="input" rows="2" maxlength="4000" placeholder="اكتب سؤالك هنا..." required></textarea><button class="btn primary" type="submit">إرسال ✦</button></form><small class="ai-note">لا ترسل كلمات مرور أو توكنات أو بيانات سرية.</small></section>');const history=[];const box=$("#ai-messages"),input=$("#ai-input");$("#ai-form").onsubmit=async e=>{e.preventDefault();const text=input.value.trim();if(!text)return;history.push({role:"user",content:text});box.insertAdjacentHTML("beforeend",'<div class="ai-message user"><b>أنت</b><p>'+esc(text)+'</p></div>');input.value="";input.disabled=true;const send=e.target.querySelector("button");send.disabled=true;const pending=document.createElement("div");pending.className="ai-message assistant ai-pending";pending.textContent="يفكر مساعد ملاذ…";box.appendChild(pending);box.scrollTop=box.scrollHeight;try{const d=await api("/api/ai/chat",{method:"POST",body:JSON.stringify({messages:history})});pending.remove();history.push({role:"assistant",content:d.answer});const msg=document.createElement("div");msg.className="ai-message assistant";const title=document.createElement("b");title.textContent="MLD AI";const p=document.createElement("p");p.textContent=d.answer;msg.append(title,p);box.appendChild(msg)}catch(err){pending.remove();const msg=document.createElement("div");msg.className="ai-message error";msg.textContent=err.message;box.appendChild(msg)}finally{input.disabled=false;send.disabled=false;input.focus();box.scrollTop=box.scrollHeight}}}
async function profile(){if(!me)return auth();getApp().innerHTML=shell("PROFILE","بروفايلي","غيّر الاسم والأفتار والنبذة.",'<form id="pf" class="form"><img class="avatar-xl" src="'+esc(me.avatar||"/logo.svg.JPG")+'"><input class="input" name="displayName" value="'+esc(me.displayName)+'" placeholder="الاسم"><input class="input" name="avatar" value="'+esc(me.avatar||"")+'" placeholder="رابط الأفتار"><textarea class="input" name="bio" placeholder="نبذة">'+esc(me.bio||"")+'</textarea><button class="btn primary">حفظ</button></form>');$("#pf").onsubmit=async e=>{e.preventDefault();try{me=await api("/api/auth/profile",{method:"PATCH",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});nav();profile();toast("تم الحفظ")}catch(x){toast(x.message)}}}
let publicChatPoll=null;
async function chat(){if(!me)return auth();getApp().innerHTML=shell("CHAT","الشات","شات عام ومحادثات خاصة متعددة الأشخاص، مع تحديث تلقائي للرسائل.",'<div class="chatgrid"><section><div id="public-chat" class="chat" aria-live="polite"></div><form id="cf" class="send"><input class="input" name="message" maxlength="2000" placeholder="اكتب رسالة" required><button class="btn primary">إرسال</button></form></section><aside class="panel"><h2>الخاص</h2><button id="newchat" class="btn primary">+ محادثة</button><div id="plist"></div></aside></div>');let busy=false;const load=async()=>{if(busy||!$("#public-chat"))return;busy=true;try{const d=await api("/api/chat");const el=$("#public-chat");if(!el)return;const atBottom=el.scrollHeight-el.scrollTop-el.clientHeight<80;el.innerHTML=d.map(x=>'<div><b>'+esc(x.name)+'</b><p>'+esc(x.message)+'</p></div>').join("")||'<div class="empty">لا توجد رسائل</div>';if(atBottom)el.scrollTop=el.scrollHeight}catch(e){if(!publicChatPoll)toast(e.message)}finally{busy=false}};await load();if(publicChatPoll)clearInterval(publicChatPoll);publicChatPoll=setInterval(()=>{if(location.hash!=="#chat"||!$("#public-chat")){clearInterval(publicChatPoll);publicChatPoll=null;return}load()},4000);$("#cf").onsubmit=async e=>{e.preventDefault();const input=e.target.elements.message;const message=input.value.trim();if(!message)return;const send=e.target.querySelector("button[type=submit]");if(send)send.disabled=true;try{await api("/api/chat",{method:"POST",body:JSON.stringify({message})});e.target.reset();await load()}catch(x){toast(x.message)}finally{if(send)send.disabled=false}};const p=await api("/api/chat/private");$("#plist").innerHTML=p.map(x=>'<button type="button" class="private" data-private="'+esc(x.id)+'">'+esc(x.name)+' <small>'+x.members.length+" أعضاء</small></button>").join("")||"<p>لا توجد محادثات.</p>";$("[data-private]").forEach(x=>x.onclick=()=>privateChat(x.dataset.private));$("#newchat").onclick=newPrivate}
async function newPrivate(){const u=await api("/api/chat/users");modal('<form id="np" class="form"><h2>محادثة خاصة</h2><input class="input" name="name" placeholder="اسم المحادثة"><div class="checks">'+u.map(x=>'<label><input type="checkbox" name="members" value="'+x.id+'">'+esc(x.displayName||x.username)+"</label>").join("")+'</div><button class="btn primary">إنشاء</button></form>');$("#np").onsubmit=async e=>{e.preventDefault();try{const members=[...e.target.querySelectorAll("[name=members]:checked")].map(x=>x.value);const c=await api("/api/chat/private",{method:"POST",body:JSON.stringify({name:e.target.name.value,members})});closeModal();privateChat(c.id)}catch(x){toast(x.message)}}}
