async function gamesPage(){getApp().innerHTML=shell("GAME HUB","الألعاب","جلسات حقيقية، أدوار وحركات محفوظة على الخادم، مع محاكاة للبوتات في الألعاب المناسبة.",'<div class="gamegrid">'+games.map(g=>'<article class="game"><span>'+g[0]+'</span><h2>'+esc(g[1])+'</h2><p>'+esc(g[2])+'</p><div>'+button("إنشاء","create:"+g[1],"primary")+button("الجلسات","sessions:"+g[1],"ghost")+"</div></article>").join("")+"</div>");}
async function createGame(game){if(!me)return auth();modal('<form id="create-game-form" class="form"><h2>إنشاء '+esc(game)+'</h2><label>الحد الأقصى للاعبين<select class="input" name="max"><option>2</option><option selected>4</option><option>6</option><option>10</option><option>20</option></select></label><label>بوتات المحاكاة<select class="input" name="botCount"><option value="0">بدون بوتات</option><option value="1">بوت واحد</option><option value="2">بوتان</option><option value="3">3 بوتات</option><option value="4">4 بوتات</option></select></label><small>ألعاب Mafia وCode Names وX تتطلب لاعبين حقيقيين.</small><button class="btn primary">إنشاء الجلسة</button></form>');$("#create-game-form").onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));const g=await api("/api/games/sessions",{method:"POST",body:JSON.stringify({game,max:Number(data.max),botCount:Number(data.botCount)})});closeModal();await room(g.id)}catch(err){toast(err.message)}}}
async function sessions(game){if(!me)return auth();const d=await api("/api/games/sessions");const a=d.filter(x=>x.game===game);modal("<h2>"+esc(game)+"</h2>"+(a.map(x=>'<div class="session"><b>'+esc(x.ownerName)+'</b><span>'+x.players.length+"/"+x.max+"</span>"+button("انضمام","join:"+x.id,"primary")+"</div>").join("")||'<div class="empty">لا توجد جلسات</div>'));$$("[data-action^=join:]").forEach(x=>x.onclick=async()=>{try{const g=await api("/api/games/sessions/"+x.dataset.action.slice(5)+"/join",{method:"POST"});closeModal();await room(g.id)}catch(e){toast(e.message)}})}
async function room(id){if(gamePoll)clearInterval(gamePoll);const load=async()=>api("/api/games/sessions/"+id);let g;try{g=await load()}catch(e){return toast(e.message)}const draw=game=>{const start=game.started?"":button("بدء اللعبة","start:"+id,"primary");modal('<small>GAME ROOM · '+(game.ended?"FINISHED":game.started?"LIVE":"LOBBY")+'</small><h2>'+esc(game.game)+'</h2><div class="players">'+game.players.map(p=>'<div><img src="/logo.svg.JPG"><b>'+esc(p.name)+'</b>'+(p.isBot?'<small>SIM BOT</small>':"")+'</div>').join("")+'</div><div class="game-status">'+(game.started?"الجولة "+(game.state?.round||1):"بانتظار بدء الجلسة")+'</div>'+start+button("مغادرة","leave:"+id,"ghost")+'<div id="gameplay"></div>');if(game.started||game.ended)renderGame(game);$("[data-action='start:"+id+"']")?.addEventListener("click",async()=>{try{await api("/api/games/sessions/"+id+"/start",{method:"POST"});const next=await load();draw(next)}catch(e){toast(e.message)}});$("[data-action='leave:"+id+"']")?.addEventListener("click",async()=>{try{await api("/api/games/sessions/"+id+"/leave",{method:"POST"});if(gamePoll)clearInterval(gamePoll);closeModal()}catch(e){toast(e.message)}})};draw(g);gamePoll=setInterval(async()=>{if(!$("#modal")||$("#modal").classList.contains("hidden")){clearInterval(gamePoll);return}try{const fresh=await load();const el=$("#gameplay");if(el&&fresh.started){renderGame(fresh)}if(fresh.ended){clearInterval(gamePoll);const target=$("#gameplay");if(target)target.insertAdjacentHTML("afterbegin",'<div class="game-result">'+esc(fresh.endReason||"انتهت اللعبة")+'</div>')}}catch{clearInterval(gamePoll)}},2500)}
function renderGame(g){const o=$("#gameplay");if(!o)return;const act=async(action,value)=>{try{await api("/api/games/sessions/"+g.id+"/action",{method:"POST",body:JSON.stringify({action,value})});const fresh=await api("/api/games/sessions/"+g.id);renderGame(fresh)}catch(e){toast(e.message)}};let html='<div class="game-live"><h3>اللعب الفعلي 🎮</h3><p>'+esc(g.endReason||"نفّذ حركتك وتابع سجل الجولة.")+'</p>';
const players=g.players.filter(p=>!p.isBot);
if(g.game==="X"){html+='<div class="x-board">'+(g.state.board||Array(9).fill("")).map((v,i)=>'<button class="x-cell" data-x="'+i+'">'+esc(v||"·")+'</button>').join("")+'</div><p>الدور: '+esc(g.players.find(p=>p.userId===g.state.turnPlayer)?.name||"—")+'</p>'}
else if(g.game==="Code Names"){html+='<div class="codenames">'+g.state.words.map((w,i)=>'<button class="word '+((g.state.guessed||[]).includes(i)?"picked":"")+'" data-word="'+i+'" '+((g.state.guessed||[]).includes(i)?"disabled":"")+'>'+esc(w)+'</button>').join("")+'</div><p>الفريق الحالي: '+esc(g.state.turn||"red")+'</p>'}
else if(g.game==="Mafia"){html+='<p>دورك: '+esc(g.ownRole==="mafia"?"مافيا سرية":g.ownRole==="citizen"?"مواطن":"—")+'</p><div class="game-controls">'+players.filter(p=>p.userId!==me.id&&(g.state.active||[]).includes(p.userId)).map(p=>button("صوّت لـ "+p.name,"vote:"+p.userId,"ghost")).join("")+'</div>'}
else if(g.game==="Roulette")html+='<p>آخر لاعب متبقٍ يفوز.</p>'+button("لف الروليت","spin","primary");
else if(g.game==="Bomb")html+='<p>حامل القنبلة: '+esc(g.players.find(p=>p.userId===g.state.bombHolder)?.name||"—")+' · الوقت '+esc(g.state.fuse||0)+'</p>'+button("مرّر القنبلة","pass","primary");
else if(g.game==="Chairs")html+='<p>الكراسي تتحرك تلقائيًا كل 15 ثانية. المتبقون: '+(g.state.active||[]).length+'</p>';
else if(g.game==="Button")html+=button("اضغط الآن!","press","primary");
else if(["Stone","Cut"].includes(g.game))html+='<div class="game-controls">'+button("حجر","choose:rock","ghost")+button("ورقة","choose:paper","ghost")+button("مقص","choose:scissors","ghost")+'</div>';
else if(g.game==="Trap")html+='<div class="game-controls">'+Array.from({length:9},(_,i)=>button("مربع "+(i+1),"trap:"+i,"ghost")).join("")+'</div>';
else if(g.game==="Hide")html+=button("اختبئ","hide","primary");
else if(g.game==="Qosar")html+='<form id="game-answer" class="game-controls"><input class="input" name="value" type="number" min="1" max="20" placeholder="توقع رقمًا من 1 إلى 20" required><button class="btn primary">تخمين</button></form>';
else if(g.game==="Capitals")html+='<p>ما عاصمة '+esc(g.state.question||"الدولة")+'؟</p>'+answerForm("اكتب العاصمة");
else if(g.game==="Akmal")html+='<p>'+esc(g.state.question||"أكمل العبارة")+'</p>'+answerForm("أكمل العبارة");
else if(g.game==="Wasel")html+='<p>الكلمة التالية تبدأ بالحرف: '+esc(g.state.lastLetter||"أي حرف")+'</p>'+answerForm("اكتب كلمة");
else if(g.game==="Salfah")html+='<p>'+esc(g.state.prompt||"أجب عن السؤال")+'</p>'+answerForm("اكتب إجابتك");
else if(g.game==="Tard")html+='<p>أرسل إجابتك قبل انتهاء الوقت.</p>'+answerForm("إجابتك");
else if(g.game==="Company")html+='<p>رصيدك: '+esc(g.state.scores?.[me.id]||0)+' نقطة. الاستثمار يحتاج 10 نقاط.</p>'+button("استثمر 10 نقاط","invest","primary");
else html+=answerForm("أرسل حركتك");
html+='<div class="game-log"><b>سجل الجولة</b>'+((g.state.log||[]).map(x=>'<p>'+esc(x.text)+'</p>').join("")||"<p>ابدأ اللعب لعرض الحركات.</p>")+'</div></div>';o.innerHTML=html;
function answerForm(placeholder){return '<form id="game-answer" class="game-controls"><input class="input" name="value" placeholder="'+placeholder+'" required><button class="btn primary">إرسال</button></form>'}
$$("[data-x]").forEach(b=>b.onclick=()=>act("move",Number(b.dataset.x)));$$("[data-word]").forEach(b=>b.onclick=()=>act("guess",Number(b.dataset.word)));$$("[data-action^=vote:]").forEach(b=>b.onclick=()=>act("vote",b.dataset.action.slice(5)));$$("[data-action^=trap:]").forEach(b=>b.onclick=()=>act("choose",Number(b.dataset.action.slice(5))));$$("[data-action^=choose:]").forEach(b=>b.onclick=()=>act("choose",b.dataset.action.slice(7)));$$("[data-action]").filter(b=>["spin","pass","press","hide","invest"].includes(b.dataset.action)).forEach(b=>b.onclick=()=>act(b.dataset.action));$("#game-answer")?.addEventListener("submit",e=>{e.preventDefault();act(g.game==="Qosar"?"guess":g.game==="Company"?"invest":"answer",e.target.value.value)})}
async function groups(){getApp().innerHTML=shell("GROUPS","القروبات","طلب إنشاء قروب Discord يمر على الأونر، وبعد القبول ينشئ البوت الفئة والشات والروم والرتبة.",(me?button("إنشاء قروب","new-group","primary"):"")+'<div id="groups" class="grid"></div>');if(me)$("#groups").insertAdjacentHTML("beforebegin",'');$("#new-group")?.addEventListener("click",newGroup);try{const d=await api("/api/groups");$("#groups").innerHTML=d.map(g=>'<article class="feature"><b>◇</b><h2>'+esc(g.name)+'</h2><p>'+esc(g.description)+'</p>'+button("طلب انضمام","join-group:"+g.id,"ghost")+"</article>").join("")||'<div class="empty">لا توجد قروبات معتمدة</div>';$$("[data-action^=join-group:]").forEach(x=>x.onclick=async()=>{if(!me)return auth();try{await api("/api/groups/"+x.dataset.action.slice(11)+"/join",{method:"POST"});toast("تم إرسال الطلب")}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
function newGroup(){modal('<form id="gf" class="form"><h2>إنشاء قروب</h2><input class="input" name="name" placeholder="اسم القروب" required><textarea class="input" name="description" placeholder="الوصف" required></textarea><button class="btn primary">إرسال للأونر</button></form>');$("#gf").onsubmit=async e=>{e.preventDefault();try{await api("/api/groups",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast("وصل الطلب للأونر")}catch(x){toast(x.message)}}}
async function cinema(){
 const [items,status]=await Promise.all([api("/api/cinema"),api("/api/cinema/status").catch(()=>({}))]);
 const canManage=me?.role==="owner";
 let body='<div class="cinema-status"><b>حالة Discord:</b> '+(status.discordConnected?"متصل":"غير متصل")+' · <b>الروم:</b> '+esc(status.voiceChannel?.name||"غير محدد")+'</div>';
 if(canManage)body+=button("إيقاف تشغيل صوت السينما","cinema-stop","danger")+'<form id="cinema-room-form" class="form"><label>الروم الصوتي<select class="input" name="voiceChannelId"><option value="">بدون روم</option></select></label><button class="btn ghost">حفظ الروم</button></form><form id="cinema-add-form" class="form"><h3>إضافة فيلم أو رابط مشاهدة</h3><input class="input" name="title" placeholder="اسم الفيلم" required><input class="input" name="url" type="url" placeholder="رابط قانوني للمشاهدة" required><textarea class="input" name="description" placeholder="وصف الفيلم"></textarea><button class="btn primary">إضافة للمكتبة</button></form>';
 body+='<div class="cinema-grid">'+(items.map(x=>{let embed=x.embedUrl?'<div class="cinema-frame"><iframe src="'+esc(x.embedUrl)+'" title="'+esc(x.title)+'" loading="lazy" allow="encrypted-media; picture-in-picture" allowfullscreen></iframe></div>':x.mediaType==="video"?'<div class="cinema-frame"><video controls playsinline src="'+esc(x.url)+'"></video></div>':x.mediaType==="audio"?'<audio controls preload="none" src="'+esc(x.url)+'"></audio>':"";return '<article class="feature"><span>🎬</span><h2>'+esc(x.title)+'</h2><p>'+esc(x.description||"جلسة مشاهدة")+'</p>'+embed+'<div class="game-controls"><a class="btn ghost" href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">فتح المشاهدة</a>'+(canManage?button("إعلان بدء الجلسة","cinema-start:"+x.id,"primary")+button("حذف","cinema-delete:"+x.id,"danger"):"")+'</div></article>'}).join("")||'<div class="empty">المكتبة فارغة. أضف محتوى تملك حق عرضه من لوحة الأونر.</div>')+'</div>';
 getApp().innerHTML=shell("CINEMA","السينما","مكتبة مشاهدة ومزامنة روابط المحتوى، مع تحديد روم صوتي وإعلان بدء الجلسة.",body);
 if(canManage){
  try{const channels=await api("/api/discord/voice-channels");$("#cinema-room-form select").innerHTML='<option value="">بدون روم</option>'+channels.map(x=>'<option value="'+esc(x.id)+'" '+(x.id===status.voiceChannel?.id?"selected":"")+'>'+esc(x.name)+'</option>').join("")}catch(e){toast(e.message)}
  $("#cinema-room-form").onsubmit=async e=>{e.preventDefault();try{await api("/api/cinema/room",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast("تم حفظ الروم");cinema()}catch(err){toast(err.message)}};
  $("#cinema-add-form").onsubmit=async e=>{e.preventDefault();try{await api("/api/cinema",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast("أضيف للمكتبة");cinema()}catch(err){toast(err.message)}};
  $('[data-action="cinema-stop"]').forEach(b=>b.onclick=async()=>{try{await api("/api/cinema/stop",{method:"POST"});toast("تم إيقاف تشغيل الصوت")}catch(err){toast(err.message)}});$("[data-action^=cinema-start:]").forEach(b=>b.onclick=async()=>{try{const d=await api("/api/cinema/start",{method:"POST",body:JSON.stringify({itemId:b.dataset.action.slice(13)})});toast(d.voicePlayback?"بدأ البوت تشغيل الصوت في الروم":d.notified?"أُعلن بدء المشاهدة في Discord":(d.playbackMessage||"بدأت جلسة المشاهدة"))}catch(err){toast(err.message)}});
  $$("[data-action^=cinema-delete:]").forEach(b=>b.onclick=async()=>{try{await api("/api/cinema/"+b.dataset.action.slice(14),{method:"DELETE"});cinema()}catch(err){toast(err.message)}});
 }
}
async function bots(){if(!me)return auth();let list=[];try{list=await api("/api/bots")}catch(e){toast(e.message)}getApp().innerHTML=shell("BOT STUDIO","إدارة البوتات","أضف بوت Discord ثم تحكم بالبادئات والاختصارات من هنا. يجب تفعيل Message Content Intent وServer Members Intent في Discord Developer Portal.",'<form id="bot-add-form" class="form"><input class="input" name="botName" placeholder="اسم اختياري للبوت"><input class="input" name="token" type="password" autocomplete="off" placeholder="توكن البوت — لا تشاركه مع أحد" required><input class="input" name="guildId" inputmode="numeric" placeholder="معرّف السيرفر (Guild ID)" required><small>يُشفّر التوكن في التخزين الدائم ولن يظهر مجددًا. فعّل Message Content Intent وServer Members Intent من بوابة مطوري Discord قبل التوصيل.</small><button class="btn primary" type="submit">التحقق وإضافة البوت</button></form><h2>بوتاتي المتصلة</h2><div id="my-bots" class="list">'+renderBots(list)+'</div>');$("#bot-add-form").onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const submit=e.target.querySelector("button[type=submit]");if(submit)submit.disabled=true;try{const bot=await api("/api/bots",{method:"POST",body:JSON.stringify(data)});toast("تمت إضافة "+bot.botName+"؛ تحقق من حالة الاتصال");e.target.reset();await bots()}catch(err){toast(err.message)}finally{if(submit)submit.disabled=false}};$$("[data-bot-settings]").forEach(form=>form.onsubmit=async e=>{e.preventDefault();const id=form.dataset.botSettings;const data=new FormData(form);const prefixes=String(data.get("prefixes")||"").split(/[,\s]+/).map(x=>x.trim()).filter(Boolean);const aliases={};for(const line of String(data.get("aliases")||"").split("\n")){const pos=line.indexOf("=");if(pos<1)continue;const key=line.slice(0,pos).trim().toLowerCase(),command=line.slice(pos+1).trim().toLowerCase();if(key&&command)aliases[key]=command}const submit=form.querySelector("button[type=submit]");if(submit)submit.disabled=true;try{await api("/api/bots/"+encodeURIComponent(id)+"/settings",{method:"PATCH",body:JSON.stringify({prefixes,aliases})});toast("تم حفظ إعدادات البوت");await bots()}catch(err){toast(err.message)}finally{if(submit)submit.disabled=false}});$$("[data-action^=bot-delete:]").forEach(b=>b.onclick=async()=>{if(!confirm("هل تريد إزالة البوت من المنصة؟"))return;try{await api("/api/bots/"+b.dataset.action.slice(11),{method:"DELETE"});toast("تمت إزالة البوت");await bots()}catch(e){toast(e.message)}})}
function renderBots(list){return list.map(b=>'<article class="bot-card"><div class="row"><div><b>'+esc(b.botName)+'</b><small>'+esc(b.guildId)+' · '+esc(b.status==="online"?"متصل":b.status==="offline"?"غير متصل":b.status)+'</small></div><span class="status-pill '+(b.status==="online"?"success":"pending")+'">'+esc(b.status==="online"?"متصل":"غير متصل")+'</span></div><form class="bot-settings form" data-bot-settings="'+esc(b.id)+'"><label>البادئات (افصل بينها بفاصلة)<input class="input" name="prefixes" value="'+esc((b.prefixes||[".","-","!"]).join(", "))+'" placeholder="., -, !" required></label><label>اختصارات تعمل بدون بادئة<textarea class="input" name="aliases" rows="3" placeholder="ترحيب=help\nمعلومات=server">'+esc(Object.entries(b.aliases||{}).map(([key,value])=>key+"="+value).join("\n"))+'</textarea></label><small>اكتب كل اختصار في سطر بصيغة اختصار=command. الأوامر غير المدعومة تُرفض.</small><button class="btn primary" type="submit">حفظ الإعدادات</button>'+button("إزالة البوت","bot-delete:"+b.id,"danger")+'</form></article>').join("")||'<div class="empty">لم تضف بوتات بعد.</div>'}
async function tickets(){if(!me)return auth();getApp().innerHTML=shell("SUPPORT","التذاكر","تذكرة تفتح محادثة مع الإدارة والأونر.",'<form id="tf" class="form"><input class="input" name="subject" placeholder="عنوان" required><textarea class="input" name="message" placeholder="اشرح طلبك" required></textarea><button class="btn primary">فتح التذكرة</button></form><div id="tl" class="list"></div>');const load=async()=>{const d=await api("/api/tickets");$("#tl").innerHTML=d.map(t=>'<button class="row" data-ticket="'+t.id+'"><b>'+esc(t.subject)+'</b><span>'+esc(t.status)+"</span></button>").join("")};await load();$("#tf").onsubmit=async e=>{e.preventDefault();try{const t=await api("/api/tickets",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});ticket(t.id)}catch(x){toast(x.message)}};$$("[data-ticket]").forEach(x=>x.onclick=()=>ticket(x.dataset.ticket))}
async function ticket(id){const d=await api("/api/tickets"),t=d.find(x=>x.id===id);if(!t)return;modal('<h2>'+esc(t.subject)+'</h2><div class="chat">'+('<div><b>'+esc(t.userName)+'</b><p>'+esc(t.message)+'</p></div>')+(t.replies||[]).map(r=>'<div><b>'+esc(r.name)+'</b><p>'+esc(r.message)+'</p></div>').join("")+'</div><form id="tr" class="send"><input class="input" name="message" placeholder="رد"><button class="btn primary">إرسال</button></form>');$("#tr").onsubmit=async e=>{e.preventDefault();try{await api("/api/tickets/"+id+"/reply",{method:"POST",body:JSON.stringify({message:e.target.message.value})});ticket(id)}catch(x){toast(x.message)}}}
async function applications(){if(!me)return auth();const q=await api("/api/applications/questions");getApp().innerHTML=shell("APPLICATION","التقديم","تقديم الإدارة يظهر للأونر فقط.",'<form id="af" class="form">'+q.questions.map((x,i)=>'<label><b>'+esc(x)+'</b><textarea class="input" name="q'+i+'" required></textarea></label>').join("")+'<button class="btn primary">إرسال</button></form>');$("#af").onsubmit=async e=>{e.preventDefault();try{await api("/api/applications",{method:"POST",body:JSON.stringify({answers:[...e.target.querySelectorAll("textarea")].map(x=>x.value)})});toast("تم إرسال التقديم");e.target.reset()}catch(x){toast(x.message)}}}
async function reviews(){const d=await api("/api/reviews");getApp().innerHTML=shell("REVIEWS","الآراء","الجميع يقدر يكتب رأيه، مع أو بدون حساب.",'<div class="reviews">'+d.map(r=>'<article><b>'+esc(r.name)+'</b><p>'+esc(r.text)+'</p></article>').join("")+'</div><form id="rfv" class="form"><input class="input" name="name" placeholder="اسمك (اختياري)"><textarea class="input" name="text" placeholder="رأيك" required></textarea><button class="btn primary">نشر الرأي</button></form>');$("#rfv").onsubmit=async e=>{e.preventDefault();try{await api("/api/reviews",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});reviews();toast("تم نشر الرأي")}catch(x){toast(x.message)}}}
function account(){if(!me)return auth();getApp().innerHTML=shell("ACCOUNT","حسابي","حسابك وصلاحيتك داخل المنصة.",'<div class="account"><img src="'+esc(me.avatar||"/logo.svg.JPG")+'"><h2>'+esc(me.displayName)+'</h2><p>@'+esc(me.username)+'</p><span>'+esc(me.role)+'</span></div>')}
async function admin(){if(!me||!["admin","owner"].includes(me.role))return go("home");let d,membersData;try{[d,membersData]=await Promise.all([api("/api/admin/applications"),api("/api/admin/members")])}catch(e){getApp().innerHTML=shell("ADMIN","الإدارة","تعذر تحميل بيانات الإدارة.",'<div class="empty">'+esc(e.message)+'</div>');return}const apps=d.applications||[],tickets=d.tickets||[],members=membersData.members||[],pending=apps.filter(a=>a.status==="pending");getApp().innerHTML=shell("ADMIN CONTROL","لوحة الإدارة","مراجعة التقديمات والإجابات والتذاكر والأعضاء من مكان واحد.",'<div class="admin-sections"><div class="admin-stat"><small>إجمالي التقديمات</small><strong>'+num(apps.length)+'</strong></div><div class="admin-stat"><small>بانتظار المراجعة</small><strong>'+num(pending.length)+'</strong></div><div class="admin-stat"><small>التذاكر المفتوحة</small><strong>'+num(tickets.filter(t=>t.status==="open").length)+'</strong></div></div><div class="admin-heading"><h2>طلبات التقديم</h2><span class="status-pill pending">'+num(pending.length)+' معلّق</span></div><div class="list">'+(apps.slice().reverse().map(a=>'<article class="application"><div class="row"><div><b>'+esc(a.name)+'</b><small>'+esc(a.createdAt||"")+'</small></div><span class="status-pill '+esc(a.status)+'">'+esc(a.status==="accepted"?"مقبول":a.status==="rejected"?"مرفوض":"بانتظار المراجعة")+'</span></div><pre>'+esc((a.answers||[]).map((answer,i)=>(i+1)+". "+answer).join("\n")||"لا توجد إجابات")+'</pre>'+(a.status==="pending"?button("قبول التقديم","accept:"+a.id,"primary")+button("رفض التقديم","reject:"+a.id,"danger"):"")+'</article>').join("")||'<div class="empty">لا توجد طلبات تقديم حتى الآن</div>')+'</div><div class="admin-heading"><h2>تذاكر الدعم</h2><span class="status-pill">'+num(tickets.length)+' تذكرة</span></div><div class="list">'+(tickets.slice().reverse().map(t=>'<div class="row"><div><b>'+esc(t.subject)+'</b><small>'+esc(t.userName)+' · '+esc(t.status)+'</small></div>'+button("فتح التذكرة","ticket:"+t.id,"primary")+(t.status==="open"?button("إغلاق","close:"+t.id,"ghost"):"")+'</div>').join("")||'<div class="empty">لا توجد تذاكر</div>')+'</div><div class="admin-heading"><h2>إدارة الأعضاء</h2><span class="status-pill">'+num(members.length)+' عضو</span></div><div class="list">'+(members.map(u=>'<div class="row member-row"><div><b>'+esc(u.displayName)+'</b><small>@'+esc(u.username)+' · '+esc(u.role)+'</small></div><span class="status-pill">'+esc(u.discordId||"بدون ربط Discord")+'</span></div>').join("")||'<div class="empty">لا يوجد أعضاء</div>')+'</div>');$$("#app [data-action^='ticket:']").forEach(x=>x.onclick=()=>ticket(x.dataset.action.slice(6)));$$("#app [data-action^='close:']").forEach(x=>x.onclick=async()=>{try{await api("/api/tickets/"+x.dataset.action.slice(6)+"/close",{method:"POST"});toast("تم إغلاق التذكرة");admin()}catch(e){toast(e.message)}});}
async function owner(){if(me?.role!=="owner")return go("home");getApp().innerHTML=shell("OWNER","لوحة الأونر","كل أدوات الإدارة الحساسة هنا فقط.",'<div class="ownergrid">'+[["logs","◉","لوقات كل شيء"],["accounts","◎","الحسابات"],["applications","✎","التقديمات"],["groups","◇","القروبات"],["zajel","➤","لوق الزاجل"],["subscriptions","♜","اشتراكات البوتات"],["private","✦","المحادثات الخاصة"],["settings","⚙","الإعدادات"],["questions","?","أسئلة التقديم"],["cinema","🎬","مكتبة السينما"],["bots","♜","بوتات الأعضاء"]].map(x=>'<button class="ownerbox" data-owner="'+x[0]+'"><b>'+x[1]+"</b><strong>"+x[2]+"</strong></button>").join("")+'</div><div id="ownerpanel"></div>');$$("[data-owner]").forEach(x=>x.onclick=()=>ownerPanel(x.dataset.owner))}
async function ownerPanel(k){const o=$("#ownerpanel");try{if(k==="logs"){const d=await api("/api/owner/logs");o.innerHTML='<div class="logs">'+d.map(x=>'<details><summary>'+esc(x.type)+' · '+esc(x.at)+'</summary><pre>'+esc(JSON.stringify(x.data,null,2))+"</pre></details>").join("")+"</div>"}else if(k==="zajel"){const d=await api("/api/owner/zajel");o.innerHTML='<div class="logs">'+d.map(x=>'<article><b>'+esc(x.senderName)+' → '+esc(x.targetName)+'</b><p>'+esc(x.message)+'</p><small>'+esc(x.at)+"</small></article>").join("")+"</div>"}else if(k==="accounts"){const d=await api("/api/owner/accounts");o.innerHTML='<div class="list">'+d.map(u=>'<div class="row"><div><b>'+esc(u.displayName)+'</b><small>@'+esc(u.username)+' · '+esc(u.role)+'</small></div>'+button(u.role==="admin"?"إزالة الإدارة":"منح الإدارة","admin:"+u.id,"ghost")+button("محادثاته","inspect:"+u.id,"primary")+button("حذف نهائي","del:"+u.id,"danger")+"</div>").join("")+"</div>"}else if(k==="applications"){const d=await api("/api/owner/applications");o.innerHTML='<div class="list">'+d.map(a=>'<article class="application"><b>'+esc(a.name)+'</b><pre>'+esc(JSON.stringify(a.answers,null,2))+"</pre>"+button("قبول","accept:"+a.id,"primary")+button("رفض","reject:"+a.id,"danger")+"</article>").join("")+"</div>"}else if(k==="groups"){const d=await api("/api/admin/groups");o.innerHTML='<div class="list">'+d.groups.filter(g=>g.status==="pending").map(g=>'<div class="row"><div><b>'+esc(g.name)+'</b><small>'+esc(g.ownerName)+'</small></div>'+button("قبول","gok:"+g.id,"primary")+button("رفض","gno:"+g.id,"danger")+"</div>").join("")||'<div class="empty">لا توجد طلبات</div>'+"</div>"}else if(k==="private"){o.innerHTML='<div class="empty">اختر حساباً من «الحسابات» لمشاهدة محادثاته.</div>'}else if(k==="subscriptions"){const [d,u]=await Promise.all([api("/api/owner/subscriptions"),api("/api/owner/accounts")]);o.innerHTML='<form id="subf" class="form"><select class="input" name="userId">'+u.map(x=>'<option value="'+x.id+'">'+esc(x.displayName)+'</option>').join("")+'</select><select class="input" name="bot"><option>حماية كاملة</option><option>ألعاب كاملة</option><option>بنك كامل</option><option>ستريك كامل</option><option>تذاكر وتقديم</option><option>برودكاست</option><option>قيفاوي</option></select><button class="btn primary">تفعيل</button></form><div class="list">'+d.map(x=>'<div class="row"><b>'+esc(x.bot)+'</b><span>'+esc(x.active?"فعال":"ملغى")+'</span>'+button(x.active?"إلغاء":"تفعيل","sub:"+x.id,"ghost")+"</div>").join("")+"</div>";$("#subf").onsubmit=async e=>{e.preventDefault();await api("/api/owner/subscriptions",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});ownerPanel(k)}}else if(k==="cinema"){const d=await api("/api/cinema"),status=await api("/api/cinema/status").catch(()=>({}));o.innerHTML='<div class="cinema-status">روم التشغيل: '+esc(status.voiceChannel?.name||"غير محدد")+' · Discord '+(status.discordConnected?"متصل":"غير متصل")+'</div><div class="list">'+d.map(x=>'<div class="row"><b>'+esc(x.title)+'</b><a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">فتح الرابط</a>'+button("حذف","cinema-delete:"+x.id,"danger")+'</div>').join("")+'</div><form id="owner-cinema-form" class="form"><h3>إضافة للمكتبة</h3><input class="input" name="title" placeholder="العنوان" required><input class="input" name="url" type="url" placeholder="رابط HTTP/HTTPS" required><textarea class="input" name="description" placeholder="الوصف"></textarea><button class="btn primary">إضافة</button></form>';$("#owner-cinema-form").onsubmit=async e=>{e.preventDefault();try{await api("/api/cinema",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});ownerPanel(k)}catch(x){toast(x.message)}};$("[data-action^=cinema-delete:]").forEach(b=>b.onclick=async()=>{try{await api("/api/cinema/"+b.dataset.action.slice(14),{method:"DELETE"});ownerPanel(k)}catch(e){toast(e.message)}})}else if(k==="bots"){const d=await api("/api/owner/bots");o.innerHTML='<div class="list">'+d.map(b=>'<div class="row"><div><b>'+esc(b.botName)+'</b><small>'+esc(b.owner)+' · '+esc(b.guildId)+' · '+esc(b.status)+'</small></div></div>').join("")+'</div>'||'<div class="empty">لا توجد بوتات مسجلة.</div>'}else if(k==="settings"){const d=await api("/api/owner/settings");o.innerHTML='<form id="sf" class="form"><input class="input" name="announcement" value="'+esc(d.announcement||"")+'"><input class="input" name="announcementColor" value="'+esc(d.announcementColor||"#c7b2bb")+'"><button class="btn primary">حفظ</button></form>';$("#sf").onsubmit=async e=>{e.preventDefault();await api("/api/owner/settings",{method:"PATCH",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});$("#announcement-text").textContent=e.target.announcement.value;$("#announcement-text").style.color=e.target.announcementColor.value||"#c7b2bb";toast("تم الحفظ")}}else if(k==="questions"){const d=await api("/api/applications/questions");o.innerHTML='<form id="qf" class="form"><textarea class="input" name="questions">'+esc(d.questions.join("\n"))+'</textarea><button class="btn primary">حفظ الأسئلة</button></form>';$("#qf").onsubmit=async e=>{e.preventDefault();await api("/api/owner/questions",{method:"PATCH",body:JSON.stringify({questions:e.target.questions.value.split("\n").map(x=>x.trim()).filter(Boolean)})});toast("تم حفظ الأسئلة")}}}catch(e){o.innerHTML='<div class="empty">'+esc(e.message)+"</div>"}}
async function ownerAction(a){try{if(a.startsWith("admin:")){const id=a.slice(6);const users=await api("/api/owner/accounts"),u=users.find(x=>x.id===id);if(u.role==="admin")await api("/api/owner/admins/"+id,{method:"DELETE"});else await api("/api/owner/admins",{method:"POST",body:JSON.stringify({userId:id})});ownerPanel("accounts")}else if(a.startsWith("del:")){if(confirm("حذف نهائي؟")){await api("/api/owner/accounts/"+a.slice(4),{method:"DELETE"});ownerPanel("accounts")}}else if(a.startsWith("inspect:")){const d=await api("/api/owner/user/"+a.slice(8)+"/private");$("#ownerpanel").innerHTML=d.map(c=>'<article class="panel"><h2>'+esc(c.name)+'</h2><div class="chat">'+c.messages.map(m=>'<div><b>'+esc(m.name)+'</b><p>'+esc(m.message)+'</p></div>').join("")+"</div></article>").join("")||'<div class="empty">لا توجد محادثات</div>'}else if(a.startsWith("accept:")||a.startsWith("reject:")){const id=a.split(":")[1];await api("/api/applications/"+id+"/status",{method:"PATCH",body:JSON.stringify({status:a.startsWith("accept:")?"accepted":"rejected"})});if(location.hash==="#admin")admin();else ownerPanel("applications")}else if(a.startsWith("gok:")||a.startsWith("gno:")){const id=a.split(":")[1];await api("/api/admin/groups/"+id+"/status",{method:"POST",body:JSON.stringify({status:a.startsWith("gok:")?"approved":"rejected"})});ownerPanel("groups")}else if(a.startsWith("sub:")){const id=a.slice(4),d=await api("/api/owner/subscriptions");const x=d.find(v=>v.id===id);await api("/api/owner/subscriptions/"+id,{method:"PATCH",body:JSON.stringify({active:!x.active})});ownerPanel("subscriptions")}}catch(e){toast(e.message)}}
function logout(){token="";me=null;localStorage.removeItem("mld_token");nav();go("home");toast("تم تسجيل الخروج")}
const pages={home,members,top,roles,chat,profile,zajel,games:gamesPage,groups,cinema,tickets,applications,reviews,account,admin,owner,ai,bots};
async function page(){let p=location.hash.slice(1)||"home";if(p==="logout"){logout();return}if(!pages[p]){p="home";if(location.hash!=="#home")history.replaceState(null,"","#home")}if(publicChatPoll){clearInterval(publicChatPoll);publicChatPoll=null}if(privateChatPoll){clearInterval(privateChatPoll);privateChatPoll=null}$("#mobile").classList.remove("open");nav();const menu=$("#menu");if(menu)menu.setAttribute("aria-expanded","false");getApp().setAttribute("aria-live","polite");try{await pages[p]()}catch(e){getApp().innerHTML='<div class="page"><div class="empty" role="alert">'+esc(e.message||"حدث خطأ غير متوقع")+"</div></div>"}}
let audioContext;function playUiSound(kind="click"){try{const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;audioContext=audioContext||new Ctx();if(audioContext.state==="suspended")audioContext.resume();const osc=audioContext.createOscillator(),gain=audioContext.createGain(),now=audioContext.currentTime;osc.type="sine";osc.frequency.setValueAtTime(kind==="success"?740:kind==="error"?220:480,now);osc.frequency.exponentialRampToValueAtTime(kind==="success"?980:kind==="error"?160:360,now+0.055);gain.gain.setValueAtTime(0.0001,now);gain.gain.exponentialRampToValueAtTime(kind==="success"?0.035:0.018,now+0.008);gain.gain.exponentialRampToValueAtTime(0.0001,now+0.075);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now);osc.stop(now+0.08)}catch{}}
document.addEventListener("click",e=>{if(e.target.closest("button,.btn,[data-page]"))playUiSound("click");const p=e.target.closest("[data-page]");if(p){e.preventDefault();go(p.dataset.page);return}const a=e.target.closest("[data-action]");if(a){const v=a.dataset.action;if(v.startsWith("owner:"))ownerAction(v.slice(6));else if(v==="new-group")newGroup();else if(v.startsWith("create:"))createGame(v.slice(7));else if(v.startsWith("sessions:"))sessions(v.slice(9));else if(v.startsWith("join:")){}else if(v.startsWith("cinema-delete:")){}else if(v.startsWith("cinema-start:")){}else if(v.startsWith("bot-delete:")){}else if(/^(admin:|del:|inspect:|accept:|reject:|gok:|gno:|sub:)/.test(v))ownerAction(v);else if(pages[v])go(v); }});
$("#menu").onclick=()=>{const mobile=$("#mobile");if(!mobile)return;const open=mobile.classList.toggle("open");$("#menu").setAttribute("aria-expanded",String(open));};$("#modal-close").onclick=closeModal;$("#modal").onclick=e=>{if(e.target.id==="modal")closeModal()};
$("#theme")?.addEventListener("click",()=>{const next=document.documentElement.dataset.theme==="light"?"dark":"light";document.documentElement.dataset.theme=next;localStorage.setItem("mld_theme",next);$("#theme").textContent=next==="light"?"☀":"◐";toast(next==="light"?"تم تفعيل الوضع الفاتح":"تم تفعيل الوضع الليلي")});
if($("#theme"))$("#theme").textContent=document.documentElement.dataset.theme==="light"?"☀":"◐";
window.addEventListener("hashchange",page);
async function boot(){
  getApp();
  if(!app){document.body.insertAdjacentHTML("beforeend",'<main id="app" style="padding:40px;color:white">MLD</main>');getApp();}
  try{me=(await api("/api/auth/me")).user}catch{}
  try{nav()}catch(e){console.error("MLD nav error",e)}
  try{const s=await api("/api/settings");const a=$("#announcement-text");if(a){a.textContent=s.announcement||"مرحباً بكم في MLD";a.style.color=s.announcementColor||"#c7b2bb"}}catch(e){console.warn("MLD settings error",e)}
  try{await page()}catch(e){console.error("MLD page error",e);getApp().innerHTML='<div class="page"><div class="empty">'+esc(e.message||e)+"</div></div>"}
}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",boot,{once:true});else boot();